class ShortBookSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["title", "author"]

matilda = Book.objects.create(title="Matilda", author="Roald Dahl")
print(ShortBookSerializer(matilda).data)

class NewestFirstViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.order_by("-id")      # which rows
    serializer_class = ShortBookSerializer       # the class itself, no ()
